tasks.starter:
// Each thread increments the shared counter 4 times => correct total is 8.
// Steps are pre-interleaved. Each non-atomic increment is split into
// a READ (snapshot the cell into a thread-local register) and a WRITE
// (store register+1 back). When the two threads' read/write steps
// overlap, an update is lost.
//
// Interleaving (R=read, W=write, letter=thread):
//   Ra Rb Wa Wb  Ra Rb Wa Wb  Ra Wa Rb Wb  Ra Wa Rb Wb
// The first two rounds overlap (Rb reads the stale value) -> 2 lost.
// The last two rounds are clean -> no loss.
const steps = [
  ['R','a'],['R','b'],['W','a'],['W','b'],
  ['R','a'],['R','b'],['W','a'],['W','b'],
  ['R','a'],['W','a'],['R','b'],['W','b'],
  ['R','a'],['W','a'],['R','b'],['W','b'],
];

function racySimulation() {
  let cell = 0;
  const reg = { a: 0, b: 0 };
  for (const [op, t] of steps) {
    if (op === 'R') reg[t] = cell;        // read into thread-local register
    else cell = reg[t] + 1;               // write register+1 back
  }
  return cell;
}

function atomicSimulation() {
  // Atomics.add collapses read-modify-write into ONE indivisible step,
  // so no interleaving can split it. Count the increments (one per WRITE).
  let cell = 0;
  for (const [op] of steps) {
    if (op === 'W') cell = cell + 1;      // indivisible: nothing lands between
  }
  return cell;
}

const racyTotal = racySimulation();
const atomicTotal = atomicSimulation();
console.log('racy=' + racyTotal + ' atomic=' + atomicTotal);
